    var sum = memory + v;
    if (!isFinite(sum)) {
      setResult(NaN);
      return;
    }
    memory = sum;
    if (state.typing) {
      state.value = v;
      state.typing = false;
      state.edited = true;
      state.entryExpr = null;
    }
  }

  // MR puts the exact memory value on the display as the entry, like typing it.
  function memoryRecall() {
    state.value = memory;
    state.typing = false;
    state.edited = true;
    state.entryExpr = null;
    if (state.op === null) state.lastOp = null;
  }

  function handle(el) {
    var digit = el.getAttribute('data-digit');
    var op = el.getAttribute('data-op');
    var action = el.getAttribute('data-action');
